    exfalso; lia.
  }
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB0LD_1RC0LD_1LB1RA_0RA1LD | exact ok_iarm1_0_1RB0LD_1RC0LD_1LB1RA_0RA1LD]. }
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB0LD_1RC0LD_1LB1RA_0RA1LD | exact ok_iarm1_1_1RB0LD_1RC0LD_1LB1RA_0RA1LD]. }
    exfalso; lia.
  }
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB0LD_1RC0LD_1LB1RA_0RA1LD | exact ok_iarm2_0_1RB0LD_1RC0LD_1LB1RA_0RA1LD]. }
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB0LD_1RC0LD_1LB1RA_0RA1LD | exact ok_iarm2_1_1RB0LD_1RC0LD_1LB1RA_0RA1LD]. }
