    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_1RB0LD_1RC0LD_1LD1RA_0RA1LD.
  - repeat constructor.
  - vm_compute; lia.
