Definition iarm_1RB0LD_1RC1LC_1LD1RA_0RC1LD (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB0LD_1RC1LC_1LD1RA_0RC1LD
  | 1, 0 => iarm1_0_1RB0LD_1RC1LC_1LD1RA_0RC1LD
  | 2, 0 => iarm2_0_1RB0LD_1RC1LC_1LD1RA_0RC1LD
  | _, _ => iarm0_0_1RB0LD_1RC1LC_1LD1RA_0RC1LD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

