  mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S0;S0] [S1;S0;S0] 1 0 []))
          (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S1;S1] [S1;S1;S1] 1 0 [S1])) 6 8.
Definition ch_farm1_0_1RB0LD_1RC1LC_1LD1RA_0RC1LD : list rstep := [RB (SWin 3);RB (SCycR 3);RB (SWinR 2);RB (SCycL 3 0);RB (SWin 3)].
