  check_arm tm true true rules farm1_0_1RB0LD_1RC1LC_1LD1RA_0RC1LD
            ch_farm1_0_1RB0LD_1RC1LC_1LD1RA_0RC1LD = true.
Proof. vm_compute. reflexivity. Qed.

(** The fill arms, one per arm index and PHASE.  Both tails are known
    empty -- they are the only arms that see the end of the counter -- and
    the arm at index [r] has [r] guaranteed block copies materialised into
    [s_pre], without which it has no chain at all.  [fm1]/[fm2] say how the
    fill target's own guaranteed copies divide about the block.

    The phase is the second index because the fill arm is the ONLY one that
    sees a terminator: it leaves from the terminator of its own phase and
    lands on the terminator of the phase its law names.  The interior arms
    keep the terminator in the opaque tail and are phase-free. *)
Definition farm_1RB0LD_1RC1LC_1LD1RA_0RC1LD (r ph : nat) : LRule :=
  match r, ph with
  | 1, 0 => farm1_0_1RB0LD_1RC1LC_1LD1RA_0RC1LD
  | _, _ => farm1_0_1RB0LD_1RC1LC_1LD1RA_0RC1LD  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_1RB0LD_1RC1LC_1LD1RA_0RC1LD (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | _, _ => 0 end.
Definition fm2_1RB0LD_1RC1LC_1LD1RA_0RC1LD (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 0 | _, _ => 0 end.

(** One chain per UNPINNED INSTRUCTION per fill arm, at the VISIT PHASE
    0.  [fire_of_run_instr] turns each into a fire of that instruction,
    and [tops_cofinal_at] says the tops of that phase keep coming.  The fill
    arm is the counter's overflow, so this is where the rare instruction of
    a sparse row is witnessed. *)
Definition vis_1RB0LD_1RC1LC_1LD1RA_0RC1LD (r : nat) (t : Instr) : list lstep :=
  match r, t with
  | 1, (StA, S0) => [SWin 2]
  | 1, (StA, S1) => [SWin 3;SCycR 3;SWinR 2;SCycL 3 0;SWin 5]
  | 1, (StB, S0) => [SWin 3]
  | 1, (StB, S1) => [SWin 3;SCycR 3;SWinR 2;SCycL 3 0;SWin 10]
  | 1, (StC, S0) => [SWin 3;SCycR 3;SWinR 1]
  | 1, (StC, S1) => [SWin 1]
  | 1, (StD, S0) => []
  | 1, (StD, S1) => [SWin 3;SCycR 3;SWinR 2]
  | _, _ => []
  end.

(** The fill runs stop short of the family's target by blanks
    the machine never writes; these count them per arm
    ([LadderCheckLiftTr.cpad]). *)
Definition padl_1RB0LD_1RC1LC_1LD1RA_0RC1LD (r ph : nat) : nat := match r, ph with | 1, 0 => 0 | _, _ => 0 end.
Definition padr_1RB0LD_1RC1LC_1LD1RA_0RC1LD (r ph : nat) : nat := match r, ph with | 1, 0 => 2 | _, _ => 0 end.

Lemma iarm_sound_1RB0LD_1RC1LC_1LD1RA_0RC1LD : forall d r,
  d < fm_b FAM - 1 -> r < 0 + 1 ->
  RuleSound tm (negb (fm_left FAM)) (fm_left FAM) (iarm_1RB0LD_1RC1LC_1LD1RA_0RC1LD d r).
Proof.
  intros d r Hd Hr. vm_compute in Hd.
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB0LD_1RC1LC_1LD1RA_0RC1LD | exact ok_iarm0_0_1RB0LD_1RC1LC_1LD1RA_0RC1LD]. }
    exfalso; lia.
  }
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB0LD_1RC1LC_1LD1RA_0RC1LD | exact ok_iarm1_0_1RB0LD_1RC1LC_1LD1RA_0RC1LD]. }
    exfalso; lia.
  }
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB0LD_1RC1LC_1LD1RA_0RC1LD | exact ok_iarm2_0_1RB0LD_1RC1LC_1LD1RA_0RC1LD]. }
    exfalso; lia.
  }
  exfalso; lia.
Qed.

