(** The machine-level theorem, at the INSTRUCTION level: the board above
    runs on the machine wrapped at the pins, and
    [LadderCheckTr.boardph_neverqhtr] turns it into [NeverQuasiHaltsTr] of
    the machine itself. *)
Theorem nqhtr_1RB0LD_1RC1LC_1LD1RA_0RC1LD : NeverQuasiHaltsTr tm_1RB0LD_1RC1LC_1LD1RA_0RC1LD.
Proof.
  eapply (boardphL_neverqhtr tm_1RB0LD_1RC1LC_1LD1RA_0RC1LD pins_1RB0LD_1RC1LC_1LD1RA_0RC1LD FAM 1
    iarm_1RB0LD_1RC1LC_1LD1RA_0RC1LD 0 1 farm_1RB0LD_1RC1LC_1LD1RA_0RC1LD 1 1 fm1_1RB0LD_1RC1LC_1LD1RA_0RC1LD fm2_1RB0LD_1RC1LC_1LD1RA_0RC1LD padl_1RB0LD_1RC1LC_1LD1RA_0RC1LD padr_1RB0LD_1RC1LC_1LD1RA_0RC1LD
    0 vis_1RB0LD_1RC1LC_1LD1RA_0RC1LD [0] 0).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
