Lemma farm_sound_1RB0RC_0LC1RA_1LA0LD_1LC0RA : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 -> RuleSound tm true true (farm_1RB0RC_0LC1RA_1LA0LD_1LC0RA r ph).
Proof.
  intros r ph H0 Hr Hph.
  destruct r as [|r].
  { exfalso; lia. }
  destruct r as [|r].
  {
    destruct ph as [|ph].
    { eapply arm_sound; [exact rules_sound_1RB0RC_0LC1RA_1LA0LD_1LC0RA | exact ok_farm1_0_1RB0RC_0LC1RA_1LA0LD_1LC0RA]. }
    exfalso; lia.
