Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB0RC_1RC1LB_0LB1RD_0RA1RA (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB0RC_1RC1LB_0LB1RD_0RA1RA
  | 0, 1 => iarm0_1_1RB0RC_1RC1LB_0LB1RD_0RA1RA
  | _, _ => iarm0_0_1RB0RC_1RC1LB_0LB1RD_0RA1RA   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_1RB0RC_1RC1LB_0LB1RD_0RA1RA : LRule :=
  mkLRule (mkC StC (mkS [S1;S1;S1] [S1;S1;S1] 1 0 [S1]) S0 (mkS [] [] 0 0 []))
          (mkC StC (mkS [S1;S1;S1;S1;S1;S1;S0;S1;S1] [S0;S1;S1] 1 0 [S1]) S0 (mkS [] [] 0 0 [])) 6 21.
