(** The machine-level theorem, at the INSTRUCTION level: the board above
    runs on the machine wrapped at the pins, and
    [LadderCheckTr.boardph_neverqhtr] turns it into [NeverQuasiHaltsTr] of
    the machine itself. *)
Theorem nqhtr_1RB0RC_1RC1LB_0LB1RD_0RA1RA : NeverQuasiHaltsTr tm_1RB0RC_1RC1LB_0LB1RD_0RA1RA.
Proof.
  apply (boardph_neverqhtr tm_1RB0RC_1RC1LB_0LB1RD_0RA1RA pins_1RB0RC_1RC1LB_0LB1RD_0RA1RA FAM 1
                           iarm_1RB0RC_1RC1LB_0LB1RD_0RA1RA 1 1
