    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_1RB0RC_1RC1LB_0LB1RD_0RA1RA.
  - repeat constructor.
  - vm_compute; lia.
  - lia.
  - exact boot_1RB0RC_1RC1LB_0LB1RD_0RA1RA.
  - lia.
  - exact iarm_sound_1RB0RC_1RC1LB_0LB1RD_0RA1RA.
  - exact iarm_lhs_1RB0RC_1RC1LB_0LB1RD_0RA1RA.
